UPDATE emp50_transport_expense
   SET emp50_date         = #{req.date}
     , emp50_start_point  = #{req.startPoint}
     , emp50_close_point  = #{req.closePoint}
     , emp50_start_time   = #{req.startTime}
     , emp50_close_time   = #{req.closeTime}
     , emp50_amt          = #{req.amt}
     , emp50_transport_cd = #{req.transportCode}
     , emp50_note         = #{req.note}
 WHERE emp50_transport_expense_id = #{req.transportExpenseId}
   AND emp50_company_id = #{companyId}
   AND emp50_person_id = #{personId}

