SELECT CASE
           WHEN EXISTS (
               SELECT 1
                 FROM emp51_relate_appr
                WHERE emp51_close_yn = 'true'
                  AND emp51_yyyymm LIKE #{yyyymm}
                  AND emp51_company_id = #{companyId}
           ) THEN 'true'
           ELSE 'false'
       END

SELECT TO_CHAR(COALESCE(MAX(emp51_reg_no::INT), 0) + 1, 'FM000')
  FROM emp51_relate_appr
 WHERE emp51_company_id = #{companyId}
   AND emp51_yyyymm LIKE #{yyyymm}
   AND emp51_person_id != #{personId}

